import json,html,csv
from pathlib import Path
BASE=Path(__file__).resolve().parent
D=json.loads((BASE/'catalogo.json').read_text(encoding='utf-8')); E=json.loads((BASE/'extra.json').read_text(encoding='utf-8'))
TOTAL=len(D); CATEGORIES=len({d['categoria'].strip() for d in D}); SOLD=sum(bool(d['esaurito']) for d in D); EXTRAS=len(E)
H=lambda s:html.escape(str(s))
money=lambda x:f'{x:.2f}'.replace('.',',')+' €'
cats=list(dict.fromkeys(d['categoria'].strip() for d in D))
with (BASE/'supplementi.csv').open('w',encoding='utf-8-sig',newline='') as f:
 w=csv.writer(f,delimiter=';',lineterminator='\n');w.writerow(['Gruppo','Supplemento','Prezzo EUR'])
 for e in E:w.writerow([e['gruppo'],e['nome'],f"{e['prezzo_eur']:.2f}".replace('.',',')])
summary='';cards=''
for c in cats:
 ds=[d for d in D if d['categoria'].strip()==c]
 summary+=f'<tr><td>{H(c.title())}</td><td>{len(ds)}</td><td>{money(min(d["prezzo_eur"] for d in ds))} – {money(max(d["prezzo_eur"] for d in ds))}</td><td>{sum(d["esaurito"] for d in ds)}</td></tr>'
 for d in ds:
  status='Esaurito' if d['esaurito'] else 'Non segnato esaurito'
  cards+=f'''<article class="dish" data-category="{H(c)}" data-out="{int(d['esaurito'])}"><div class="dish-meta">{H(c.title())}<span class="{'soldout' if d['esaurito'] else 'available'}">{status}</span></div><div class="dish-title"><h3>{H(d['nome'])}</h3><strong>{money(d['prezzo_eur'])}</strong></div><p>{H(d['descrizione']) or 'Nessuna descrizione pubblicata.'}</p></article>'''
extra=''.join(f'<div class="extra-row"><span>{H(e["nome"])}</span><strong>+{money(e["prezzo_eur"])}</strong></div>' for e in E)
options=''.join(f'<option value="{H(c)}">{H(c.title())}</option>' for c in cats)
page='''<!DOCTYPE html><html lang="it"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Regina Sofia — Verifica menu e ordini</title><meta name="description" content="Rilevazione indipendente del menu pubblico Regina Sofia: 98 voci, 49 supplementi e punti da migliorare nell’esperienza di ordine."><style>
:root{--ink:#222e2b;--muted:#68736f;--green:#234e41;--cream:#f7f6f0;--line:#dedfd5;--orange:#bc602e}*{box-sizing:border-box}html{scroll-behavior:smooth;scroll-padding-top:84px}body{margin:0;background:var(--cream);color:var(--ink);font:16px/1.6 system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}a{color:var(--green)}.wrap{max-width:1120px;margin:auto;padding:0 28px}header{background:var(--green);color:white;padding:17px 0}header .wrap{display:flex;align-items:center;justify-content:space-between;gap:20px}.brand{font:600 20px Georgia,serif}.label{font-size:11px;text-transform:uppercase;letter-spacing:1.8px}header a{color:white;font-size:13px;text-decoration:none}.hero{padding:60px 0 32px}.eyebrow{color:var(--orange);font-size:12px;letter-spacing:2px;font-weight:700;text-transform:uppercase}h1{font:normal clamp(34px,5vw,58px)/1.1 Georgia,serif;margin:14px 0 22px;max-width:800px}h2{font:normal 31px/1.25 Georgia,serif;margin:0 0 16px}h3{line-height:1.35}.intro{max-width:750px;color:var(--muted);font-size:18px}.actions{display:flex;flex-wrap:wrap;gap:12px;margin:25px 0}.button{display:inline-block;border:0;cursor:pointer;font:inherit;background:var(--green);color:white;padding:11px 18px;border-radius:7px;text-decoration:none;font-size:14px;font-weight:600}.button.secondary{background:white;color:var(--green);border:1px solid var(--line)}.stats{display:grid;grid-template-columns:repeat(4,1fr);margin:35px 0 25px;background:white;border:1px solid var(--line);border-radius:10px}.stat{padding:23px;border-right:1px solid var(--line)}.stat:last-child{border:0}.stat b{font:normal 36px Georgia,serif;display:block;color:var(--green)}.stat span{font-size:13px;color:var(--muted)}nav{position:sticky;top:0;background:var(--cream);border-bottom:1px solid var(--line);z-index:3}nav .wrap{display:flex;gap:25px;overflow-x:auto}nav a{padding:16px 0;text-decoration:none;white-space:nowrap;font-size:14px}section{padding:40px 0;border-bottom:1px solid var(--line)}.note{background:#eeeade;padding:17px 20px;border-radius:8px;color:#5b584b;font-size:14px}.muted{color:var(--muted)}.table-wrap{overflow-x:auto;border:1px solid var(--line);border-radius:8px;background:white;margin:22px 0}table{border-collapse:collapse;width:100%;font-size:14px;white-space:nowrap}th,td{text-align:left;padding:13px 18px;border-bottom:1px solid #eeeee6}th{font-weight:600;background:#f0f2eb;font-size:12px}tr:last-child td{border:0}.findings{display:grid;grid-template-columns:1fr 1fr;gap:18px}.finding{background:white;border:1px solid var(--line);border-radius:9px;padding:23px}.finding h3{font-size:17px;margin:9px 0 10px}.finding p{font-size:14px;color:var(--muted);margin:0}.tag{font-size:10px;font-weight:700;letter-spacing:1px;color:var(--orange);text-transform:uppercase}.filters{display:grid;grid-template-columns:2fr 1fr 1fr;gap:12px;margin:25px 0 14px}.field label{display:block;font-size:12px;color:var(--muted);margin-bottom:5px}input,select{width:100%;font:inherit;font-size:14px;padding:13px 12px;border:1px solid #bac2b9;border-radius:7px;background:white;color:var(--ink)}input:focus,select:focus,a:focus-visible,summary:focus-visible{outline:3px solid #c19753;outline-offset:3px}.menu-grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}.dish{background:white;padding:19px 21px;border:1px solid var(--line);border-radius:8px}.dish-meta{display:flex;justify-content:space-between;gap:8px;font-size:10px;text-transform:uppercase;letter-spacing:.4px;color:var(--muted)}.soldout{color:#9a452e}.available{color:#467157}.dish-title{display:flex;justify-content:space-between;gap:16px;margin:10px 0 6px}.dish-title h3{font-size:15px;font-weight:650;margin:0}.dish-title strong{white-space:nowrap;font-size:15px}.dish p{font-size:13px;color:var(--muted);line-height:1.6;margin:0}.dish[hidden]{display:none}.extra-grid{display:grid;grid-template-columns:1fr 1fr;gap:0 35px;margin-top:22px}.extra-row{display:flex;justify-content:space-between;gap:20px;padding:12px 0;border-bottom:1px solid var(--line);font-size:14px}.extra-row strong{white-space:nowrap}.steps{padding-left:23px}.steps li{padding:7px 0 9px 9px}.steps strong{display:block}.steps span{font-size:14px;color:var(--muted)}details{margin-top:20px}summary{cursor:pointer;font-weight:600;padding:10px 0}.small{font-size:13px}footer{padding:28px 0 45px;color:var(--muted);font-size:12px}#empty{padding:35px;text-align:center;background:white;border-radius:8px}[hidden]{display:none!important}@media(max-width:650px){.wrap{padding:0 19px}.hero{padding:35px 0 22px}.label{display:none}.stats{grid-template-columns:1fr 1fr}.stat{padding:16px}.stat:nth-child(2){border-right:0}.stat:nth-child(-n+2){border-bottom:1px solid var(--line)}.findings,.menu-grid,.extra-grid{grid-template-columns:1fr}.filters{grid-template-columns:1fr 1fr}.field:first-child{grid-column:1/-1}h2{font-size:28px}section{padding:30px 0}.dish{padding:17px}.dish-meta{font-size:9px}.intro{font-size:16px}nav .wrap{gap:21px}.table-wrap{margin-left:0}th,td{padding:11px 13px}}@media print{nav,.filters,.actions{display:none}.hero{padding-top:20px}.dish{break-inside:avoid}.wrap{max-width:none}.menu-grid{gap:8px}body{background:white}}
</style></head><body><header><div class="wrap"><div class="brand">Regina Sofia <span class="label">/ Verifica pubblica</span></div><a href="https://delivery.reginasofia.it/" target="_blank" rel="noopener">Sito originale ↗</a></div></header><main><div class="wrap hero"><div class="eyebrow">Menu & esperienza d’ordine · 05 ottobre 2026</div><h1>Il menu attuale.<br>Una base concreta per migliorare.</h1><p class="intro">Prezzi, disponibilità dichiarata e punti da sistemare, rilevati sul sito pubblico. Un inventario consultabile per lavorare su browser mobile, WebView e app con gli stessi dati.</p><div class="actions"><a class="button" href="#menu">Esplora tutti i prezzi ↓</a><a class="button secondary" href="../ordina/">Nuovo frontend demo</a><a class="button secondary" href="../regina-sofia/">Hub progetto</a><a class="button secondary" href="catalogo.csv" download>Scarica menu CSV</a><a class="button secondary" href="supplementi.csv" download>Scarica supplementi CSV</a></div><div class="stats"><div class="stat"><b>@@TOTAL@@</b><span>voci pubblicate</span></div><div class="stat"><b>@@CATEGORIES@@</b><span>categorie</span></div><div class="stat"><b>@@SOLD@@</b><span>voci segnate esaurite</span></div><div class="stat"><b>@@EXTRAS@@</b><span>supplementi nei dati pubblici</span></div></div><p class="small muted">Questo è un report, non un nuovo servizio ordini. Il sito originale e l’app non sono stati modificati. Nessun ordine inviato.</p></div><nav aria-label="Sezioni del report"><div class="wrap"><a href="#sintesi">Sintesi prezzi</a><a href="#verifica">Cosa ho trovato</a><a href="#menu">Menu completo</a><a href="#supplementi">Supplementi</a><a href="#miglioramenti">Prossimi interventi</a></div></nav><div class="wrap">
<section id="sintesi"><div class="eyebrow">01 / Inventario</div><h2>Tutte le categorie, a colpo d’occhio</h2><p class="muted">Intervalli dei prezzi base pubblicati, comprese le voci esaurite. Non includono supplementi o eventuali costi di consegna.</p><div class="table-wrap"><table><thead><tr><th>Categoria</th><th>Voci</th><th>Prezzo da – a</th><th>Esaurite</th></tr></thead><tbody>@@SUMMARY@@</tbody></table></div><div class="note"><strong>Attenzione ai vini:</strong> il prezzo principale va da 12,00 € a 26,00 €. Nelle descrizioni sono indicati anche prezzi al calice da 4,00 € a 7,00 €: non sono lo stesso prezzo e non è stata verificata l’ordinabilità del calice online.</div></section>
<section id="verifica"><div class="eyebrow">02 / Osservazioni</div><h2>Cosa emerge dal sito attuale</h2><div class="findings"><article class="finding"><span class="tag">Dato verificato</span><h3>Due duplicazioni da controllare</h3><p>“PANNA COTTA” compare due volte a 5,00 €. “PROFITEROLES - Copy” e “PROFITEROLES” compaiono entrambi a 6,00 €. La panna cotta senza glutine è una voce distinta, non è stata considerata un duplicato.</p></article><article class="finding"><span class="tag">Dato verificato</span><h3>Quasi il 39% del menu è esaurito</h3><p>@@SOLD@@ voci su @@TOTAL@@ risultano esaurite al momento della rilevazione. In particolare: 11 dolci su 14, 4 contorni su 5 e tutte le 6 voci della dispensa. È una fotografia del sito, non una verifica delle scorte reali.</p></article><article class="finding"><span class="tag">Test mobile · 390 × 844</span><h3>La scelta del servizio precede l’ordine</h3><p>All’ingresso si apre “Scegli un servizio”, con ritiro o consegna. Nel percorso ritiro, a locale chiuso, compaiono “Più tardi”, calendario e orario. Ho selezionato il 6 ottobre alle 19:15 senza inviare un ordine. Nel DOM compare poi “Inizia ordine”.</p></article><article class="finding"><span class="tag">Interfaccia pubblica</span><h3>Categorie presenti, ricerca non individuata</h3><p>La navigazione per le @@CATEGORIES@@ categorie è presente. Nel menu iniziale testato non ho individuato una ricerca per piatto o ingrediente. A 390 px la pagina non presenta un’eccedenza orizzontale misurabile; ciò non sostituisce un test su dispositivi reali.</p></article><article class="finding"><span class="tag">Qualità contenuti</span><h3>Nomi e descrizioni da uniformare</h3><p>Tra i refusi pubblicati: “Ruccola”, “Scagli di grana”, “Wrustel di pollo”, “for di latte” e “dal flm”. Nel catalogo qui sotto i testi sono conservati come pubblicati, senza correzioni silenziose.</p></article><article class="finding"><span class="tag">Da verificare nell’app</span><h3>La conferma ordine merita un test dedicato</h3><p>Nel codice pubblico c’è un avviso personalizzato che invita ad attivare le notifiche o ricaricare la pagina, senza chiuderla, per ottenere conferma. Non ne è stata verificata la visualizzazione al checkout, né il funzionamento delle notifiche nell’app.</p></article></div><details><summary>Metodo e limiti della verifica</summary><p class="small muted">Fonte: HTML e dati del menu incorporati nella pagina pubblica https://delivery.reginasofia.it/, acquisiti il 5 ottobre 2026, e navigazione Chromium con viewport mobile 390 × 844. Aperta anche la pagina desktop. I 98 prezzi principali e i badge “Esaurito” provengono dalle schede effettivamente pubblicate; i 49 supplementi dal gruppo “Aggiungi Ingredienti” nei dati pubblici. Le descrizioni e gli eventuali prezzi al calice sono conservati nel catalogo. Non sono stati verificati tutti i supplementi singolarmente nel carrello. Non testati: pagamento, invio dell’ordine, conferma finale, tariffe per uno specifico indirizzo, app installata, WebView reale, notifiche native o sincronizzazione con il gestionale. “Non segnato esaurito” non garantisce ordinabilità immediata. I prezzi possono cambiare dopo questa rilevazione.</p></details></section>
<section id="menu"><div class="eyebrow">03 / Catalogo completo</div><h2>@@TOTAL@@ voci, con il prezzo originale</h2><p class="muted">Cerca un nome o un ingrediente, oppure seleziona una categoria. I duplicati restano visibili per consentire la revisione.</p><div class="filters"><div class="field"><label for="search">Cerca nel menu</label><input id="search" type="search" placeholder="Es. margherita, bufala, pistacchio…"></div><div class="field"><label for="category">Categoria</label><select id="category"><option value="">Tutte le categorie</option>@@OPTIONS@@</select></div><div class="field"><label for="stock">Stato pubblicato</label><select id="stock"><option value="">Tutte le voci</option><option value="0">Non esaurite</option><option value="1">Esaurite</option></select></div></div><div class="actions filter-actions"><button class="button secondary" type="button" id="reset">Azzera filtri</button><button class="button secondary" type="button" id="print">Stampa report</button></div><p id="count" class="small muted" aria-live="polite">@@TOTAL@@ voci mostrate</p><div class="menu-grid">@@CARDS@@</div><p id="empty" hidden>Nessuna voce trovata. Prova un altro nome o cambia i filtri.</p></section>
<section id="supplementi"><div class="eyebrow">04 / Personalizzazione</div><h2>@@EXTRAS@@ supplementi pubblicati</h2><p class="muted">Gruppo “Aggiungi Ingredienti”, da +0,50 € a +10,00 €. La presenza del gruppo varia per prodotto; l’applicabilità non è stata verificata su ogni piatto.</p><div class="note">Esempio di prezzo: Regina Margherita 7,50 € + cornicione ripieno 3,50 € = <strong>11,00 €</strong>, prima di eventuali altri costi. È un calcolo dai prezzi pubblicati, non un totale di checkout verificato.</div><div class="extra-grid">@@EXTRA@@</div></section>
<section id="miglioramenti"><div class="eyebrow">05 / Proposta operativa</div><h2>Meglio di una semplice WebView</h2><p class="muted">Questi sono interventi proposti, non funzionalità già realizzate o assenze accertate nell’app.</p><ol class="steps"><li><strong>Prima: ripulire e unificare il catalogo.</strong><span>Eliminare duplicati confermati, correggere testi e distinguere prezzi al calice, formati e supplementi. Usare un’unica fonte di prezzi e disponibilità per sito, app e gestionale.</span></li><li><strong>Poi: rendere più rapida la scelta sul telefono.</strong><span>Ricerca, categorie facili da raggiungere, foto coerenti, filtro per nascondere gli esauriti e informazioni sugli allergeni validate dal ristorante. Mostrare servizio, orario e costi prima di procedere.</span></li><li><strong>Un ordine chiaro, dall’aggiunta alla conferma.</strong><span>Scheda prodotto con totale aggiornato, carrello persistente e riepilogo accessibile. Stato dell’ordine recuperabile anche dopo chiusura e riapertura dell’app, senza dipendere da un refresh manuale.</span></li><li><strong>Funzioni che danno valore all’app.</strong><span>Riordino da storico, preferiti, indirizzi salvati con consenso e notifiche sugli stati dell’ordine. Verificare pulsante Indietro, tastiera, login persistente e ritorno dal pagamento su Android e iOS.</span></li></ol><div class="note"><strong>Per il confronto con l’app:</strong> occorre il link alla versione attuale o al progetto. Il test del sito mobile non certifica il comportamento della WebView o dell’app installata.</div></section>
</div></main><footer><div class="wrap">Report di rilevazione, non collegato al sistema ordini. Fonte: <a href="https://delivery.reginasofia.it/" target="_blank" rel="noopener">delivery.reginasofia.it</a> · 05/10/2026<br><a href="catalogo.csv" download>Menu CSV</a> · <a href="supplementi.csv" download>Supplementi CSV</a> · <a href="catalogo.json" download>Dati menu JSON</a></div></footer><script>const search=document.querySelector('#search'),category=document.querySelector('#category'),stock=document.querySelector('#stock'),dishes=[...document.querySelectorAll('.dish')];const norm=s=>s.toLocaleLowerCase('it').normalize('NFD').replace(/[\\u0300-\\u036f]/g,'');function filter(){const q=norm(search.value.trim());let n=0;for(const d of dishes){const show=(!q||norm(d.textContent).includes(q))&&(!category.value||d.dataset.category===category.value)&&(!stock.value||d.dataset.out===stock.value);d.hidden=!show;if(show)n++}document.querySelector('#count').textContent=n+' '+(n===1?'voce mostrata':'voci mostrate')+' su @@TOTAL@@';document.querySelector('#empty').hidden=n!==0}search.addEventListener('input',filter);category.addEventListener('change',filter);stock.addEventListener('change',filter);document.querySelector('#reset').addEventListener('click',()=>{search.value='';category.value='';stock.value='';filter();search.focus()});document.querySelector('#print').addEventListener('click',()=>window.print());</script></body></html>'''
for k,v in [('SUMMARY',summary),('CARDS',cards),('OPTIONS',options),('EXTRA',extra),('TOTAL',str(TOTAL)),('CATEGORIES',str(CATEGORIES)),('SOLD',str(SOLD)),('EXTRAS',str(EXTRAS))]: page=page.replace('@@'+k+'@@',v)
(BASE/'index.html').write_text(page,encoding='utf-8')
